package com.mannvaasam.controller;
import com.mannvaasam.service.AuthService; import jakarta.validation.constraints.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/auth") public class AuthController {final AuthService s;AuthController(AuthService s){this.s=s;} record Register(@NotBlank String name,@Email String email,@Size(min=8)String password,String phone){} record Login(@Email String email,@NotBlank String password){} @PostMapping("/register") Map<String,String> register(@RequestBody @jakarta.validation.Valid Register r){return Map.of("token",s.register(r.name,r.email,r.password,r.phone));} @PostMapping("/login") Map<String,String> login(@RequestBody @jakarta.validation.Valid Login r){return Map.of("token",s.login(r.email,r.password));} @PostMapping("/logout") Map<String,String> logout(){return Map.of("message","Discard JWT on client");}}